export interface AdaptiveRouter {
  route(ctx: RouterContext, opts?: RouterOptions): Promise<RouterDecision>;
  recordExecution(record: ExecutionRecord): Promise<void>;
  inferTaskType(signals: TaskSignals): import('./types').TaskType;
}

export interface AdaptiveRouterOptions {
  /** Ruta del archivo JSON de histÃ³rico. */
  historyPath: string;
  /** Opciones por defecto del router. */
  routerOptions?: RouterOptions;
  /** Si es false, nunca se usa exploraciÃ³n automÃ¡tica (V3). Por defecto true. */
  enableExploration?: boolean;
  /** FunciÃ³n para extraer la familia de un modelo. */
  modelFamilyExtractor?: (model: string) => string | undefined;
  /** Opciones para el clasificador de tareas (umbrales de contexto grande, etc.). */
  taskClassifierOptions?: TaskClassifierOptions;
  /**
   * Generador de aleatoriedad para la exploracion controlada (V3).
   * Inyectable para hacer los tests deterministas. Por defecto Math.random.
   */
  random?: () => number;
  /** Directorio para el session summary store (continuaciÃ³n de tareas). */
  sessionStoreDir?: string;
  /** Opciones para la cache inteligente de decisiones del router. */
  cacheOptions?: OptimizerCacheOptions;
}

export function createAdaptiveRouter(config: AdaptiveRouterOptions): AdaptiveRouter {
  const history = new JsonHistoryStore({ filePath: config.historyPath });
  const baseRouterOptions = { ...DEFAULT_ROUTER_OPTIONS, ...(config.routerOptions ?? {}) };
  const enableExploration = config.enableExploration ?? true;
  const taskClassifierOptions = config.taskClassifierOptions ?? {};
  const random = config.random ?? Math.random;
  const sessionStore = config.sessionStoreDir ? new SessionSummaryStore({ storeDir: config.sessionStoreDir }) : null;
  const cache = new OptimizerCache(config.cacheOptions);

  return {
    inferTaskType(signals) {
      return classifyTask(signals, taskClassifierOptions);
    },

    async route(ctx, opts) {
      const analysis = analyzeTask(ctx.signals, taskClassifierOptions);
      const taskType = analysis.taskType;
      const options = { ...baseRouterOptions, ...(opts ?? {}) };

      // DetecciÃ³n de continuaciÃ³n: si existe una sesiÃ³n previa similar,
      // inyectar su contexto en la decisiÃ³n.
      let resumeContext: string | undefined;
      if (sessionStore) {
        const continuation = sessionStore.findContinuation(ctx.signals.query ?? '', process.cwd());
        if (continuation) {
          resumeContext = sessionStore.buildResumePrompt(continuation);
        }
      }

      // Cache hit: si no hay continuaciÃ³n y la cache tiene una decision reciente,
      // devolverla directamente para ahorrar computo.
      if (!resumeContext) {
        const cached = cache.get(ctx.model, taskType, ctx.signals.query ?? '');
        if (cached) {
          return { ...cached, reason: `[CACHE] ${cached.reason}` };
        }
      }

      let decision: RouterDecision;

      if (enableExploration) {
        const result = await selectOptimizerWithExploration(
          ctx.model,
          taskType,
          { history },
          options,
          random,
          undefined,
          analysis,
        );
        decision = result.decision;
      } else {
        const { selectOptimizer } = await import('./selector/optimizer-selector');
        decision = await selectOptimizer(ctx.model, taskType, { history }, options, undefined, analysis);
      }

      if (resumeContext) {
        decision.resumeContext = resumeContext;
        decision.reason = `[CONTINUACION DETECTADA] ${decision.reason}`;
      }

      // Guardar en cache para futuras peticiones identicas (solo si hay evidencia).
      if (!resumeContext && decision.version !== 'V0') {
        cache.set(ctx.model, taskType, ctx.signals.query ?? '', decision);
      }

      return decision;
    },

    async recordExecution(record) {
      await history.add(record);
      // Invalidar cache para este modelo+tarea tras nueva evidencia.
      cache.invalidate(record.model, record.taskType);
    },
  };
}

export function buildContextFromQuery(
  model: string,
  query: string,
  base: Partial<TaskSignals> = {},
): RouterContext {
  const signals = extractSignalsFromQuery(query, base);
  return { model, signals };
}

export function buildRecord(
  ctx: RouterContext,
  optimizer: Optimizer,
  metrics: ExecutionRecord['metrics'],
  modelFamilyExtractor?: (model: string) => string | undefined,
  taskClassifierOptions?: TaskClassifierOptions,
): ExecutionRecord {
  const extractor = modelFamilyExtractor ?? extractModelFamily;
  return createExecutionRecord(
    ctx.model,
    extractor(ctx.model),
    classifyTask(ctx.signals, taskClassifierOptions),
    optimizer,
    metrics,
    {
      fileCount: ctx.signals.fileCount,
      contextSizeBytes: ctx.signals.contextSizeBytes,
      toolCallsExpected: ctx.signals.toolCallsExpected,
    },
  );
}

