/**
 * Valida y corrige los valores de RouterOptions para mantenerlos en rangos razonables.
 * Lanza error si valores criticos estan fuera de rango.
 */
export function validateRouterOptions(opts: Partial<RouterOptions>): Partial<RouterOptions> {
  const result: Partial<RouterOptions> = { ...opts };
  if (opts.minConfidence !== undefined && (opts.minConfidence < 0 || opts.minConfidence > 1)) {
    throw new Error(`minConfidence debe estar entre 0 y 1, recibido: ${opts.minConfidence}`);
  }
  if (
    opts.bayesMinConfidence !== undefined &&
    (opts.bayesMinConfidence < 0 || opts.bayesMinConfidence > 1)
  ) {
    throw new Error(
      `bayesMinConfidence debe estar entre 0 y 1, recibido: ${opts.bayesMinConfidence}`,
    );
  }
  if (
    opts.explorationRate !== undefined &&
    (opts.explorationRate < 0 || opts.explorationRate > 1)
  ) {
    throw new Error(`explorationRate debe estar entre 0 y 1, recibido: ${opts.explorationRate}`);
  }
  if (opts.minSamples !== undefined && opts.minSamples < 0) {
    result.minSamples = Math.max(0, opts.minSamples);
  }
  if (opts.latencyWeight !== undefined && opts.latencyWeight < 0) {
    result.latencyWeight = Math.max(0, opts.latencyWeight);
  }
  if (opts.toolingCostWeight !== undefined && opts.toolingCostWeight < 0) {
    result.toolingCostWeight = Math.max(0, opts.toolingCostWeight);
  }
  if (opts.minSavingsPercent !== undefined && opts.minSavingsPercent < 0) {
    result.minSavingsPercent = Math.max(0, opts.minSavingsPercent);
  }
  if (opts.minSavingsTokens !== undefined && opts.minSavingsTokens < 0) {
    result.minSavingsTokens = Math.max(0, opts.minSavingsTokens);
  }
  if (opts.routingOverheadTokens !== undefined && opts.routingOverheadTokens < 0) {
    result.routingOverheadTokens = Math.max(0, opts.routingOverheadTokens);
  }
  if (
    opts.familyConfidenceWeight !== undefined &&
    (opts.familyConfidenceWeight < 0 || opts.familyConfidenceWeight > 1)
  ) {
    throw new Error(
      `familyConfidenceWeight debe estar entre 0 y 1, recibido: ${opts.familyConfidenceWeight}`,
    );
  }
  if (opts.maxFailureRate !== undefined && (opts.maxFailureRate < 0 || opts.maxFailureRate > 1)) {
    throw new Error(`maxFailureRate debe estar entre 0 y 1, recibido: ${opts.maxFailureRate}`);
  }
  if (opts.minQuality !== undefined && (opts.minQuality < 0 || opts.minQuality > 1)) {
    throw new Error(`minQuality debe estar entre 0 y 1, recibido: ${opts.minQuality}`);
  }
  if (
    opts.uncertaintyPenaltyFactor !== undefined &&
    (opts.uncertaintyPenaltyFactor < 0 || opts.uncertaintyPenaltyFactor > 1)
  ) {
    throw new Error(
      `uncertaintyPenaltyFactor debe estar entre 0 y 1, recibido: ${opts.uncertaintyPenaltyFactor}`,
    );
  }
  if (opts.minEvidenceForDecision !== undefined && opts.minEvidenceForDecision < 0) {
    result.minEvidenceForDecision = Math.max(0, opts.minEvidenceForDecision);
  }
  return result;
}

